# --- self-checks ---
assert len(pages) == 24, len(pages)
assert [p["pdfPage"] for p in pages] == list(range(129, 153))
for p in pages:
    assert set(p.keys()) == {"pdfPage","bookPage","kind","section","chapter","banner","pageType","lessonNo","elements","exerciseCount","keyNumbers","manipulatives","isGame","confidence","notes"}
    for e in p["elements"]:
        assert set(e.keys()) == {"kind","title","detail"}
bp = [p["bookPage"] for p in pages if p["bookPage"] is not None]
assert bp == list(range(123, 145)), bp

with open("authoring/page-map-chunks/chunk-h.json", "w", encoding="utf-8") as f:
    json.dump(doc, f, ensure_ascii=False, indent=2)

